fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have equal length, we can iterate over their pairs
    // and produce a boolean vector indicating a[i] < b[i].
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x < y)
        .collect()
}